c_program:
#include <stdio.h>
#include <stdlib.h>

struct TreeNode {
    int data;
    struct TreeNode* left;
    struct TreeNode* right;
};

struct TreeNode* createNode(int val) {
    struct TreeNode* n = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    n->data = val;
    n->left = NULL;
    n->right = NULL;
    return n;
}

struct TreeNode* insertBST(struct TreeNode* root, int val) {
    if (root == NULL) return createNode(val);
    if (val < root->data) root->left = insertBST(root->left, val);
    else if (val > root->data) root->right = insertBST(root->right, val);
    return root;
}

struct TreeNode* searchBST(struct TreeNode* root, int key) {
    if (root == NULL || root->data == key) return root;
    if (key < root->data) return searchBST(root->left, key);
    return searchBST(root->right, key);
}

void inorder(struct TreeNode* root) {
    if (root) {
        inorder(root->left);
        printf("%d ", root->data);
        inorder(root->right);
    }
}

void preorder(struct TreeNode* root) {
    if (root) {
        printf("%d ", root->data);
        preorder(root->left);
        preorder(root->right);
    }
}

void postorder(struct TreeNode* root) {
    if (root) {
        postorder(root->left);
        postorder(root->right);
        printf("%d ", root->data);
    }
}

int treeHeight(struct TreeNode* root) {
    if (root == NULL) return -1;
    int lh = treeHeight(root->left);
    int rh = treeHeight(root->right);
    return 1 + (lh > rh ? lh : rh);
}

int countLeaves(struct TreeNode* root) {
    if (root == NULL) return 0;
    if (root->left == NULL && root->right == NULL) return 1;
    return countLeaves(root->left) + countLeaves(root->right);
}

int main(void) {
    struct TreeNode* root = NULL;
    int values[] = {50, 30, 20, 40, 70, 60, 80};
    for (int i = 0; i < 7; i++) root = insertBST(root, values[i]);

    printf("Inorder Traversal:   "); inorder(root); printf("\n");
    printf("Preorder Traversal:  "); preorder(root); printf("\n");
    printf("Postorder Traversal: "); postorder(root); printf("\n");
    printf("Tree Height: %d\n", treeHeight(root));
    printf("Leaf Node Count: %d\n", countLeaves(root));
    return 0;
}
